{
  var selPoly = geometry as Polygon;
  return await QueuedTask.Run(() =>
  {
    //note: the selected elements may belong to more than one layer...
    var elems = MapView.Active.SelectElements(selPoly, SelectionCombinationMethod.New);
    return true;
  });
}

